use crate::ir::builder::GlobalBuilder;
use crate::ir::dfg::DataFlowGraph;
use crate::ir::idman::{is_global_id, next_func_id, next_global_value_id};
use crate::ir::idman::{BasicBlockId, FunctionId, ValueId};
