    fn assign_v1_to_v2(&mut self, v1: Value, v2: Value) -> Vec<String> {
        let (reg, mut codes) = self.want_to_visit_value(v1, true, None);
        if let Some(other_reg) = self.__is_value_in_register(v2) {
            if other_reg != reg {
                codes.extend(self.save_register(other_reg));
            }
        }
        self.__update_user(reg, v2);
        codes
    }

    /// Example:
    /// getelemptr @a, 114 -> The absolute location of @a in memory.
    /// getelemptr %0, 514 -> The value of %0 (which is an address).
    fn get_absolute_location(&mut self, value: Value) -> (usize, Vec<String>) {
        let value_data = if value.is_global() {
            self.program.borrow_value(value).clone()
        } else {
            self.fd.dfg().value(value).clone()
        };
        match value_data.kind() {
            ValueKind::GlobalAlloc(_) => {
                let (reg, mut codes) = self.get_tmp_reg();
                if let Some(name) = value_data.name() {
                    codes.push(format!("  la\t{}, {}", REGISTER_NAMES[reg], assembly_symbol_name(name)));
                }
                (reg, codes)
            }
            ValueKind::Alloc(_) => {
                let (reg, mut codes) = self.get_tmp_reg();
                let offset = self
                    .local_value_location
                    .get(&value)
                    .copied()
                    .expect("missing local stack slot for alloc") as isize;
                codes.extend(self.add_with_offset(reg, offset));
                (reg, codes)
            }
            _ => self.want_to_visit_value(value, true, None),
        }
    }
