                return Err(format!("Duplicate symbol in current scope: {}", ident.content));
            }

            let shape = build_shape(shape_exps, program, my_ir_generator_info)?;
            let ty = Type::get(if shape.is_empty() {
                btype.content.clone()
            } else {
                get_array_type(btype, &shape)
            });

            if my_ir_generator_info.curr_func.is_none() {
                let init = match (shape.is_empty(), init_val) {
                    (true, Some(init_val)) => build_scalar_init_value(
                        init_val,
                        true,
                        program,
                        my_ir_generator_info,
                    )?,
                    (true, None) => create_zero_init_value(ty.clone(), program, my_ir_generator_info),
                    (false, Some(init_val)) => build_array_init_value(
                        init_val,
                        &shape,
                        true,
                        program,
                        my_ir_generator_info,
                    )?,
                    (false, None) => create_zero_init_value(ty.clone(), program, my_ir_generator_info),
                };
                let global = program.new_value().global_alloc(init);
                program.set_value_name(global, Some(format!("@{}", ident.content)));
