fn get_valuedata(
    value: Value,
    program: &mut Program,
    my_ir_generator_info: &mut MyIRGeneratorInfo,
) -> ValueData {
    if value.is_global() {
        program.borrow_value(value).clone()
    } else {
        program
            .func(my_ir_generator_info.curr_func.unwrap())
            .dfg()
            .value(value)
            .clone()
    }
}

